fn place(arr: Vec<f32>, mask: Vec<bool>, vals: Vec<f32>) -> Vec<f32> {
    assert_eq!(
        arr.len(),
        mask.len(),
        "The input array and mask must have the same length"
    );
    assert!(
        !vals.is_empty(),
        "The replacement values array must be non-empty"
    );

    let mut result = Vec::with_capacity(arr.len());
    let mut replacement_iter = vals.into_iter().cycle();

    for (value, use_replacement) in arr.into_iter().zip(mask.into_iter()) {
        if use_replacement {
            // Safe to unwrap because `cycle()` never returns None.
            result.push(replacement_iter.next().unwrap());
        } else {
            result.push(value);
        }
    }

    result
}

